package cryptosquare

import (
	"math"
	"strings"
)

// Encode normalizes the plaintext, arranges it into a rectangle as
// square as possible, and returns the encoded text read down the
// columns, with chunks separated by spaces.
func Encode(pt string) string {
	// Normalize: keep only letters and digits, lower-cased.
	var b strings.Builder
	for _, r := range pt {
		if r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' {
			b.WriteRune(toLower(r))
		}
	}
	s := b.String()
	n := len(s)
	if n == 0 {
		return ""
	}

	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := (n + c - 1) / c

	var out strings.Builder
	for j := 0; j < c; j++ {
		if j > 0 {
			out.WriteByte(' ')
		}
		for i := 0; i < r; i++ {
			idx := i*c + j
			if idx < n {
				out.WriteByte(s[idx])
			} else {
				out.WriteByte(' ')
			}
		}
	}
	return out.String()
}

func toLower(r rune) rune {
	if r >= 'A' && r <= 'Z' {
		return r + ('a' - 'A')
	}
	return r
}
