package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

// Encode normalizes the plaintext (lower-casing it and removing spaces and
// punctuation), arranges the normalized characters into a rectangle as
// square as possible, and returns the text read down the columns, with the
// resulting chunks separated by spaces. Cells beyond the end of the message
// are padded with a single trailing space per chunk.
func Encode(pt string) string {
	// Normalize: keep only letters and digits, lower-cased.
	var runes []rune
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			if lr := unicode.ToLower(r); lr != 0 {
				r = lr
			}
			runes = append(runes, r)
		}
	}

	n := len(runes)
	if n == 0 {
		return ""
	}

	// Rectangle dimensions: smallest c with c >= r and c - r <= 1,
	// which is c = ceil(sqrt(n)) and r = ceil(n / c).
	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := (n + c - 1) / c

	var b strings.Builder
	b.Grow(n + c - 1)
	for j := 0; j < c; j++ {
		if j > 0 {
			b.WriteByte(' ')
		}
		for i := 0; i < r; i++ {
			if idx := i*c + j; idx < n {
				b.WriteRune(runes[idx])
			} else {
				b.WriteByte(' ')
			}
		}
	}
	return b.String()
}
